import{_ as e}from"./chunks/mac-security-settings.DOF-7oNi.js";import{_ as i,o,c as s,ae as r}from"./chunks/framework.Czhw_PXq.js";const g=JSON.parse('{"title":"Problema común de instalación en macOS - Solución a \\"la aplicación está dañada\\"","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/mac-installation-issue.md","filePath":"es/guide/mac-installation-issue.md"}'),n={name:"es/guide/mac-installation-issue.md"};function t(l,a,c,d,p,u){return o(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="problema-comun-de-instalacion-en-macos-solucion-a-la-aplicacion-esta-danada" tabindex="-1">Problema común de instalación en macOS - Solución a &quot;la aplicación está dañada&quot; <a class="header-anchor" href="#problema-comun-de-instalacion-en-macos-solucion-a-la-aplicacion-esta-danada" aria-label="Permalink to &quot;Problema común de instalación en macOS - Solución a &quot;la aplicación está dañada&quot;&quot;">​</a></h1><p>Cuando instale OTools u otras aplicaciones de terceros en macOS, puede encontrar un mensaje similar a &quot;xxx.app está dañado, no se puede abrir, debería moverlo a la Papelera&quot;. Esto generalmente se debe a la configuración de seguridad de macOS.</p><h2 id="¿por-que-sucede-esto" tabindex="-1">¿Por qué sucede esto? <a class="header-anchor" href="#¿por-que-sucede-esto" aria-label="Permalink to &quot;¿Por qué sucede esto?&quot;">​</a></h2><p>macOS tiene un control muy estricto sobre los programas en comparación con Windows. Las aplicaciones que no son de la App Store a menudo muestran mensajes como &quot;xxx.app está dañado&quot; durante la instalación. Desde macOS 10.15, Apple ha restringido aún más los permisos para aplicaciones sin firmar, lo que hace que estos problemas sean más frecuentes.</p><h2 id="soluciones" tabindex="-1">Soluciones <a class="header-anchor" href="#soluciones" aria-label="Permalink to &quot;Soluciones&quot;">​</a></h2><h3 id="metodo-1-configuracion-para-permitir-aplicaciones-descargadas-desde-cualquier-lugar" tabindex="-1">Método 1: Configuración para permitir aplicaciones descargadas desde &quot;Cualquier lugar&quot; <a class="header-anchor" href="#metodo-1-configuracion-para-permitir-aplicaciones-descargadas-desde-cualquier-lugar" aria-label="Permalink to &quot;Método 1: Configuración para permitir aplicaciones descargadas desde &quot;Cualquier lugar&quot;&quot;">​</a></h3><ol><li>Abra &quot;Preferencias del Sistema -&gt; Seguridad y privacidad -&gt; General&quot;</li><li>Verifique si la opción &quot;Permitir apps descargadas desde&quot; ya tiene habilitada la opción &quot;Cualquier lugar&quot;</li><li>Si no está habilitada, haga clic en el pequeño icono de candado en la parte inferior izquierda para desbloquear, luego seleccione &quot;Cualquier lugar&quot;</li></ol><p><img src="'+e+'" alt=""></p><p>Si no ve la opción &quot;Cualquier lugar&quot; en la configuración, abra Terminal e introduzca el siguiente comando:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --master-disable</span></span></code></pre></div><p>Introduzca la contraseña de inicio de sesión de su computadora según se solicite y presione Intro. Después de eso, verá aparecer la opción &quot;Cualquier lugar&quot; en la configuración.</p><p>Normalmente después de esta configuración, la aplicación se puede instalar normalmente. Sin embargo, si su versión de macOS es más reciente, aún podría necesitar intentar el siguiente método.</p><h3 id="metodo-2-evadir-la-notarizacion-de-gatekeeper-de-apple" tabindex="-1">Método 2: Evadir la notarización de Gatekeeper de Apple <a class="header-anchor" href="#metodo-2-evadir-la-notarizacion-de-gatekeeper-de-apple" aria-label="Permalink to &quot;Método 2: Evadir la notarización de Gatekeeper de Apple&quot;">​</a></h3><p>Si el Método 1 aún no resuelve el problema, puede intentar los siguientes pasos:</p><ol><li>Abra Terminal</li><li>Introduzca el siguiente comando, pero no pulse Intro todavía:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span></span></code></pre></div><ol start="3"><li>En Finder, localice OTools.app en la carpeta Aplicaciones</li><li>Arrastre OTools.app a la ventana de Terminal, lo que agregará automáticamente la ruta de la aplicación al comando</li><li>Pulse Intro, introduzca su contraseña y después de completar, podrá ejecutar directamente la aplicación</li></ol><h3 id="metodo-3-clic-derecho-para-abrir-adecuado-para-primera-instalacion" tabindex="-1">Método 3: Clic derecho para Abrir (Adecuado para primera instalación) <a class="header-anchor" href="#metodo-3-clic-derecho-para-abrir-adecuado-para-primera-instalacion" aria-label="Permalink to &quot;Método 3: Clic derecho para Abrir (Adecuado para primera instalación)&quot;">​</a></h3><p>Para instalaciones por primera vez, también puede probar:</p><ol><li>Busque OTools.app en Finder</li><li>Haga clic derecho (o mantenga presionada la tecla Control mientras hace clic)</li><li>Seleccione &quot;Abrir&quot;</li><li>Haga clic en &quot;Abrir&quot; en la ventana emergente de advertencia de seguridad</li></ol><h2 id="notas-importantes" tabindex="-1">Notas Importantes <a class="header-anchor" href="#notas-importantes" aria-label="Permalink to &quot;Notas Importantes&quot;">​</a></h2><ul><li>OTools es una aplicación de escritorio legítima construida usando el framework Tauri</li><li>Su computadora no está afectada por software malicioso</li><li>Este problema es causado por las políticas de seguridad de Apple, no por la aplicación en sí</li></ul>',22)])])}const q=i(n,[["render",t]]);export{g as __pageData,q as default};
